alter table public.leave_requests add column if not exists client_event_id uuid,add column if not exists decision_notes text;
create unique index if not exists idx_leave_requests_client_event on public.leave_requests(organization_id,staff_id,client_event_id) where client_event_id is not null;
alter table public.timesheets add column if not exists review_notes text;

drop policy if exists leave_requests_insert on public.leave_requests;drop policy if exists leave_requests_update on public.leave_requests;drop policy if exists leave_requests_select on public.leave_requests;
create policy leave_requests_select on public.leave_requests for select to authenticated using(public.is_admin_for_org(organization_id) or exists(select 1 from public.staff_profiles sp where sp.id=leave_requests.staff_id and (sp.user_id=auth.uid() or sp.id=auth.uid())));
revoke all on public.leave_requests from public,anon,authenticated;grant select on public.leave_requests to authenticated;grant all on public.leave_requests to service_role;

drop policy if exists timesheets_admin_insert on public.timesheets;drop policy if exists timesheets_admin_update on public.timesheets;drop policy if exists timesheets_select on public.timesheets;drop policy if exists timesheets_officer_self on public.timesheets;
create policy timesheets_select on public.timesheets for select to authenticated using(public.is_admin_for_org(organization_id) or exists(select 1 from public.staff_profiles sp where sp.id=timesheets.staff_id and (sp.user_id=auth.uid() or sp.id=auth.uid())));
revoke all on public.timesheets from public,anon,authenticated;grant select on public.timesheets to authenticated;grant all on public.timesheets to service_role;

drop policy if exists shift_coverage_insert on public.shift_coverage_requests;drop policy if exists shift_coverage_update on public.shift_coverage_requests;
revoke insert,update,delete on public.shift_coverage_requests from public,anon,authenticated;

create function public.submit_officer_leave_request(p_client_event_id uuid,p_leave_type text,p_starts_on date,p_ends_on date,p_reason text default null)
returns table(id uuid,created boolean,status text) language plpgsql volatile security definer set search_path=public as $$
declare v_user uuid:=auth.uid();v_staff public.staff_profiles%rowtype;v_leave public.leave_requests%rowtype;
begin
  select sp.* into v_staff from public.staff_profiles sp join public.user_profiles up on up.id=v_user and up.deactivated_at is null where sp.organization_id=up.organization_id and (sp.user_id=v_user or sp.id=v_user) limit 1;if not found then raise exception 'Active staff profile required';end if;
  if p_client_event_id is null then raise exception 'client_event_id is required';end if;if p_leave_type not in('annual','sick','bereavement','parental','unpaid','other') then raise exception 'Unsupported leave type';end if;if p_starts_on is null or p_ends_on is null or p_starts_on>p_ends_on or p_ends_on-p_starts_on>366 then raise exception 'Leave period is outside the accepted range';end if;
  select l.* into v_leave from public.leave_requests l where l.organization_id=v_staff.organization_id and l.staff_id=v_staff.id and l.client_event_id=p_client_event_id;if found then return query select v_leave.id,false,v_leave.status;return;end if;
  if exists(select 1 from public.leave_requests l where l.staff_id=v_staff.id and l.status in('pending','approved') and daterange(l.starts_on,l.ends_on,'[]')&&daterange(p_starts_on,p_ends_on,'[]')) then raise exception 'An active leave request already overlaps this period';end if;
  insert into public.leave_requests(organization_id,staff_id,leave_type,starts_on,ends_on,status,reason,client_event_id) values(v_staff.organization_id,v_staff.id,p_leave_type,p_starts_on,p_ends_on,'pending',nullif(trim(coalesce(p_reason,'')),''),p_client_event_id) returning * into v_leave;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_staff.organization_id,v_user,'leave_request_submitted','leave_requests',v_leave.id,jsonb_build_object('staff_id',v_staff.id,'leave_type',p_leave_type,'starts_on',p_starts_on,'ends_on',p_ends_on));return query select v_leave.id,true,v_leave.status;
end;$$;

create function public.review_leave_request(p_request_id uuid,p_expected_status text,p_decision text,p_review_notes text default null)
returns public.leave_requests language plpgsql volatile security definer set search_path=public as $$
declare v_actor uuid:=auth.uid();v_leave public.leave_requests%rowtype;v_notes text:=nullif(trim(coalesce(p_review_notes,'')),'');
begin
  select l.* into v_leave from public.leave_requests l where l.id=p_request_id for update;if not found then raise exception 'Leave request not found';end if;if not public.is_admin_for_org(v_leave.organization_id) then raise exception 'Not authorised to review this leave request';end if;if v_leave.status<>p_expected_status then raise exception 'Leave request changed from expected status % to %',p_expected_status,v_leave.status;end if;if v_leave.status<>'pending' or p_decision not in('approved','declined') then raise exception 'Unsupported leave decision';end if;if p_decision='declined' and v_notes is null then raise exception 'Review notes are required to decline leave';end if;
  if p_decision='approved' and exists(select 1 from public.roster_slots s where s.staff_id=v_leave.staff_id and s.status not in('declined','cancelled') and daterange((s.scheduled_start at time zone 'Pacific/Auckland')::date,(s.scheduled_end at time zone 'Pacific/Auckland')::date,'[]')&&daterange(v_leave.starts_on,v_leave.ends_on,'[]')) then raise exception 'Active roster slots overlap this leave request';end if;
  update public.leave_requests set status=p_decision,approved_by=v_actor,approved_at=clock_timestamp(),decision_notes=v_notes where id=v_leave.id returning * into v_leave;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_leave.organization_id,v_actor,case when p_decision='approved' then 'leave_request_approved' else 'leave_request_declined' end,'leave_requests',v_leave.id,jsonb_build_object('staff_id',v_leave.staff_id,'starts_on',v_leave.starts_on,'ends_on',v_leave.ends_on,'review_notes',v_notes));return v_leave;
end;$$;

create function public.review_timesheet(p_timesheet_id uuid,p_expected_status text,p_decision text,p_review_notes text default null)
returns public.timesheets language plpgsql volatile security definer set search_path=public as $$
declare v_actor uuid:=auth.uid();v_sheet public.timesheets%rowtype;v_notes text:=nullif(trim(coalesce(p_review_notes,'')),'');
begin
  select t.* into v_sheet from public.timesheets t where t.id=p_timesheet_id for update;if not found then raise exception 'Timesheet not found';end if;if not public.is_admin_for_org(v_sheet.organization_id) then raise exception 'Not authorised to review this timesheet';end if;if v_sheet.status<>p_expected_status then raise exception 'Timesheet changed from expected status % to %',p_expected_status,v_sheet.status;end if;if v_sheet.status<>'submitted' or p_decision not in('approved','rejected') then raise exception 'Unsupported timesheet decision';end if;if p_decision='rejected' and v_notes is null then raise exception 'Review notes are required to reject a timesheet';end if;if v_sheet.actual_hours is null then raise exception 'Actual hours are required before review';end if;
  update public.timesheets set status=p_decision,approved_by=v_actor,approved_at=clock_timestamp(),review_notes=v_notes where id=v_sheet.id returning * into v_sheet;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_sheet.organization_id,v_actor,case when p_decision='approved' then 'timesheet_approved' else 'timesheet_rejected' end,'timesheets',v_sheet.id,jsonb_build_object('staff_id',v_sheet.staff_id,'period_start',v_sheet.period_start,'period_end',v_sheet.period_end,'actual_hours',v_sheet.actual_hours,'overtime_hours',v_sheet.overtime_hours,'review_notes',v_notes));return v_sheet;
end;$$;

create function public.create_shift_coverage_request(p_organization_id uuid,p_shift_date date,p_start_time time,p_end_time time,p_required_staff_count integer default 1,p_urgency text default 'normal',p_notes text default null)
returns public.shift_coverage_requests language plpgsql volatile security definer set search_path=public as $$
declare v_actor uuid:=auth.uid();v_row public.shift_coverage_requests%rowtype;
begin if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to create coverage requests';end if;if p_shift_date<current_date or p_start_time is null or p_end_time is null or p_start_time=p_end_time then raise exception 'Coverage timing is invalid';end if;if p_required_staff_count not between 1 and 50 then raise exception 'Required staff count is outside the accepted range';end if;if p_urgency not in('low','normal','high','urgent') then raise exception 'Unsupported coverage urgency';end if;insert into public.shift_coverage_requests(organization_id,shift_date,start_time,end_time,required_staff_count,urgency,notes,created_by)values(p_organization_id,p_shift_date,p_start_time,p_end_time,p_required_staff_count,p_urgency,nullif(trim(coalesce(p_notes,'')),''),v_actor)returning * into v_row;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(p_organization_id,v_actor,'shift_coverage_request_created','shift_coverage_requests',v_row.id,jsonb_build_object('shift_date',p_shift_date,'start_time',p_start_time,'end_time',p_end_time,'required_staff_count',p_required_staff_count,'urgency',p_urgency));return v_row;end;$$;

revoke all on function public.submit_officer_leave_request(uuid,text,date,date,text),public.review_leave_request(uuid,text,text,text),public.review_timesheet(uuid,text,text,text),public.create_shift_coverage_request(uuid,date,time,time,integer,text,text) from public,anon;
grant execute on function public.submit_officer_leave_request(uuid,text,date,date,text),public.review_leave_request(uuid,text,text,text),public.review_timesheet(uuid,text,text,text),public.create_shift_coverage_request(uuid,date,time,time,integer,text,text) to authenticated,service_role;